    ops_old = '<div class="panel" id="operationsPanel"><div class="section-head"><h2>صحة التشغيل والإنتاج V13.17.1</h2><span class="muted">تراقب جودة المصدر، سلامة الجلسة، الأدلة وجاهزية المراجعة التنفيذية اليدوية.</span></div><div class="body"><div class="cards" id="opsCards"></div>'
    ops_new = '<div class="panel" id="operationsPanel"><div class="section-head"><h2>صحة النظام V13.19</h2><span class="muted">تطابق الجلسات، جودة البيانات، التغطية الحديثة وجاهزية المراجعة اليدوية.</span></div><div class="body">' + HEALTH_INSERT + '<div class="cards" id="opsCards"></div>'
