    text = text.replace('<h1>V13.18 — مركز القرار والمحفظة</h1>', '<h1>V13.19 — التوصيات والمحفظة والمخاطر</h1>', 1)
    text = text.replace('إصدار تشغيلي يجمع توصيات اليوم مع متابعة دورة حياة الصفقات المفتوحة، مع بقاء التنفيذ لدى الوسيط يدويًا.', 'إصدار متابعة متكامل: سجل التوصيات، دورة حياة الصفقة، مخاطر المحفظة وصحة النظام، مع بقاء التنفيذ لدى الوسيط يدويًا.', 1)
    text = text.replace("metric('واجهة المحفظة','13.18'),metric('محرك الإنتاج','13.17.1')", "metric('واجهة المتابعة','13.19'),metric('محفظة الصفقات','13.18'),metric('محرك الإنتاج','13.17.1')", 1)
